const regionLabelsJa: Record<string, string> = { Japan: "日本", "East Asia": "東アジア", "Southeast Asia": "東南アジア", "South Asia": "南アジア", "Central Asia": "中央アジア", Oceania: "オセアニア", Europe: "ヨーロッパ", Americas: "南北アメリカ", "South America": "南アメリカ", Africa: "アフリカ", "Middle East": "中東", Special: "特殊地点" };
function cityName(city: Point) { return state.lang === "ja" ? cityLabelsJa[city.name] || cityLabelsJaExtra[city.name] || city.name : city.name; }
function cityRegion(city: Point) { return cityRegions[city.name] || cityRegionsExtra[city.name] || militaryRegions[city.name] || "Other"; }
function cityRegionLabel(region: string) { return state.lang === "ja" ? regionLabelsJa[region] || region : region; }
function isMajorCity(city: Point) { return majorCities.has(city.name) || additionalMajorCities.has(city.name) || city.name === "Null Island" || city.name.includes("Pole"); }
function cityMatchesCategory(city: Point, category: CityCategory) { if (category === "all") return true; if (category === "heritage") return worldHeritageCityNames.has(city.name); return categorySets[category].has(city.name) || (category === "tourism" && worldHeritageCityNames.has(city.name)); }

function parseHeritageCoordinates(value: unknown): [number, number] | null {
  if (Array.isArray(value) && value.length >= 2) {
    const lat = Number(value[0]), lng = Number(value[1]);
    return Number.isFinite(lat) && Number.isFinite(lng) ? [lng, lat] : null;
  }
  if (typeof value === "string") {
    const parts = value.split(",").map(Number);
    if (parts.length >= 2 && parts.every(Number.isFinite)) return [parts[1], parts[0]];
  }
  if (value && typeof value === "object") {
    const item = value as Record<string, unknown>;
    const lat = Number(item.lat ?? item.latitude), lng = Number(item.lon ?? item.lng ?? item.longitude);
    if (Number.isFinite(lat) && Number.isFinite(lng)) return [lng, lat];
  }
  return null;
}

async function loadWorldHeritageData() {
  heritageDataStatus = "loading";
  render();
  try {
    const sites: [number, number][] = [];
    for (let offset = 0; offset < 2000; offset += 100) {
      const response = await fetch(`https://data.unesco.org/api/explore/v2.1/catalog/datasets/whc001/records?limit=100&offset=${offset}`);
      if (!response.ok) throw new Error(`UNESCO request failed: ${response.status}`);
      const payload = await response.json() as { results?: unknown[] };
      const rows = payload.results || [];
      for (const row of rows) {
        const item = row as Record<string, any>;
        const fields = item.record?.fields || item.fields || item;
        const coordinate = parseHeritageCoordinates(fields.coordinates ?? fields.coordinate);
        if (coordinate) sites.push(coordinate);
      }
      if (rows.length < 100) break;
    }
    if (!sites.length) throw new Error("UNESCO returned no coordinates");
    heritageSiteCount = sites.length;
    for (const site of sites) {
      let nearest: Point | null = null;
      let nearestDistance = Infinity;
      for (const city of cities) {
        const distance = d3.geoDistance(site, city.coord);
        if (distance < nearestDistance) { nearest = city; nearestDistance = distance; }
      }
      if (nearest && nearestDistance <= 50 / 6371) worldHeritageCityNames.add(nearest.name);
    }
    heritageDataStatus = "loaded";
  } catch {
    heritageDataStatus = "fallback";
  }
  refreshCityOptions();
  render();
}

